import {precision} from './precision.js';
// Native non-destructive straight-corner evaluator. Original nodes remain editable.
export function cornerEligible(o){return o?.type==='path'&&o.closed&&o.nodes.length>=3&&!o.subpaths?.length&&!o.source&&!o.panelOf&&!o.structureKey&&o.category!=='structure'&&!o.component&&!o.construction&&!o.modifiers?.length&&o.nodes.every((n,i)=>!n.in&&!n.out&&Math.hypot(n.x-o.nodes[(i+1)%o.nodes.length].x,n.y-o.nodes[(i+1)%o.nodes.length].y)>precision.zeroLength);}
export function cornerLimit(o){return Math.min(...o.nodes.map((n,i)=>Math.hypot(n.x-o.nodes[(i+1)%o.nodes.length].x,n.y-o.nodes[(i+1)%o.nodes.length].y)))/2;}
export function evaluateCorners(o){const c=o.liveCorners;if(!c||c.enabled===false||!c.radius||!cornerEligible({...o,liveCorners:undefined}))return o;const radius=Math.max(0,Math.min(c.radius,cornerLimit(o))),nodes=[];for(let i=0;i<o.nodes.length;i++){const n=o.nodes[i],prev=o.nodes[(i+o.nodes.length-1)%o.nodes.length],next=o.nodes[(i+1)%o.nodes.length],A={x:prev.x-n.x,y:prev.y-n.y},B={x:next.x-n.x,y:next.y-n.y},la=Math.hypot(A.x,A.y),lb=Math.hypot(B.x,B.y),dot=(A.x*B.x+A.y*B.y)/(la*lb),angle=Math.acos(Math.max(-1,Math.min(1,dot))),distance=Math.min(la/2,lb/2,radius/Math.max(.0001,Math.tan(angle/2))),a={x:n.x+A.x/la*distance,y:n.y+A.y/la*distance,nid:n.nid+'-a'},b={x:n.x+B.x/lb*distance,y:n.y+B.y/lb*distance,nid:n.nid+'-b'};if(c.type!=='chamfer'){const actualRadius=distance*Math.tan(angle/2),k=4/3*Math.tan((Math.PI-angle)/4)*actualRadius;a.out={x:a.x-A.x/la*k,y:a.y-A.y/la*k};b.in={x:b.x-B.x/lb*k,y:b.y-B.y/lb*k};if(c.type==='inverse'){const center={x:a.x+b.x-n.x,y:a.y+b.y-n.y};a.out={x:a.x+(center.x-a.x)*.55228475,y:a.y+(center.y-a.y)*.55228475};b.in={x:b.x+(center.x-b.x)*.55228475,y:b.y+(center.y-b.y)*.55228475};}}nodes.push(a,b);}return {...o,nodes};}
